def check_tournament(m, n, remembered_points):
    # Check if the sum of points for each player can match the remembered points
    total_points = [0] * m
    for i in range(m):
        for j in range(m):
            if i != j:
                total_points[i] += 2  # Assume the worst case scenario (win)
    for i in range(n):
        if total_points[i] != remembered_points[i]:
            return "no"
    return "yes"

def generate_tournament(m, n, remembered_points):
    # Generate a valid tournament table
    tournament = [['X' if i == j else 'D' for j in range(m)] for i in range(m)]
    total_points = [0] * m
    for i in range(m):
        for j in range(m):
            if i != j:
                tournament[i][j] = 'W'
                total_points[i] += 2
    for i in range(n):
        for j in range(m):
            if total_points[i] == remembered_points[i]:
